package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.IfMatchVersion;
@RestController @RequestMapping("/api/planning/important-dates") public class PlanningImportantDateController {private final PlanningImportantDateService s;public PlanningImportantDateController(PlanningImportantDateService s){this.s=s;}@PostMapping public Mono<PlanningImportantDateView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreatePlanningImportantDateRequest r){return s.create(o,r);}@GetMapping public Flux<PlanningImportantDateView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return s.list(o);}@PatchMapping("/{dateId}")public Mono<ResponseEntity<PlanningImportantDateView>> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID dateId,@RequestHeader(value="If-Match",required=false)String ifMatch,@Valid@RequestBody UpdatePlanningImportantDateRequest r){long version=IfMatchVersion.parse(ifMatch);return s.update(o,dateId,new UpdatePlanningImportantDateRequest(r.title(),r.description(),r.occursAt(),r.timeZone(),r.kind(),version)).map(view->ResponseEntity.ok().eTag(IfMatchVersion.etag(view.version())).body(view));}@DeleteMapping("/{dateId}")public Mono<ResponseEntity<PlanningImportantDateView>> archive(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID dateId,@RequestHeader(value="If-Match",required=false)String ifMatch){return s.archive(o,dateId,IfMatchVersion.parse(ifMatch)).map(view->ResponseEntity.ok().eTag(IfMatchVersion.etag(view.version())).body(view));}}
